pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public { c = new DnGmxBatchingManager(); }
    function testFuzz_property(address nonOwner, address newOwner) public {
        vm.assume(newOwner != address(0));
        address initialOwner = c.owner();
        vm.assume(nonOwner != initialOwner);

        vm.prank(nonOwner);
        try c.transferOwnership(newOwner) {
        } catch {
            assertEq(c.owner(), initialOwner);
            return;
        }

        assertEq(c.owner(), initialOwner, "Ownership should not change when called by non-owner");
    }
}
